// =============================================================================
// HQ Housing, normalise one form submission into a flat lead object
// =============================================================================
// The RENT form was rebuilt in 2026:
//   new     : language, profession, gross_income, search_area, search_city_other,
//             ams_ring, referral_name
//   renamed : occupation -> situation, living -> household
//   values  : furnished is now yes / no / no_preference
//   optional: duration, source, about may all arrive empty
// The BUY form is unchanged; its branch below is untouched.

const data = $input.first().json.body || $input.first().json;

const mode = (data.mode || 'rent').toLowerCase();
const isBuy = mode === 'buy';

// --- Monday.com: renting board column ids ------------------------------------
// The new answers need new columns on the board. Create each one, then paste
// its id here. Anything left as '' is skipped, so this node keeps working
// (and keeps writing everything else) until you get round to it.
const RENT_COLUMNS = {
  firstName:    'text_mkt1ywt2',
  lastName:     'text_mkt1nswv',
  dateOfBirth:  'date_mkt2h0kx',
  situation:    'text_mkt1gra2',
  profession:   'text_mkt1wp59',  // used to be a second copy of occupation
  targetCity:   'text_mkt1kq6d',
  budget:       'text_mkt1gn6w',
  homeType:     'text_mkt181r9',
  duration:     'text_mkwfcdh1',
  household:    'text_mkxssyh8',
  phone:        'text_mkt176g0',
  email:        'text_mkt1dtwa',
  nlRegistered: 'text_mkwfmkhq',
  fullAddress:  'text_mkt1c9vy',
  moveInDate:   'text_mkt17dvr',
  furnished:    'text_mkt1q9eq',
  source:       'text_mkt2mfqf',
  about:        'text_mkwfzgct',
  submittedAt:  'date_mkt1aetr',

  // New columns — paste the ids once they exist on the board
  language:     '',
  grossIncome:  '',
  neighbourhood:'',
  ring:         '',
  referralName: '',
};

// --- Option label maps -------------------------------------------------------
// Legacy values from the old form are kept so historical replays still read well.
const LANGUAGES = { nl: 'Dutch (NL)', en: 'English (EN)', fr: 'French (FR)', es: 'Spanish (ES)' };

const SITUATIONS = {
  employed: 'Employed', self_employed: 'Self-employed', student: 'Student',
  other: 'Other', freelancer: 'Self-employed'
};

const HOUSEHOLDS = {
  single: 'Single', couple: 'Couple', sharing: 'Sharing',
  alone: 'Single', shares: 'Sharing'
};

// Short codes for the sheet and the Monday board — they match the ~150 rows of
// history already in those columns. The notification email uses the long form.
const HOME_TYPES = {
  studio: 'Studio', '1br': '1br', '2br': '2br', '3br+': '3br+', house: 'House'
};

const HOME_TYPES_LONG = {
  studio: 'Studio', '1br': '1-bedroom apartment', '2br': '2-bedroom apartment',
  '3br+': 'More than 2 bedrooms', house: 'House'
};

const FURNISHED = {
  yes: 'Furnished', no: 'Unfurnished', no_preference: 'No preference',
  furnished: 'Furnished', unfurnished: 'Unfurnished',
  upholstered: 'Upholstered', none: 'No preference'
};

const RINGS = {
  inside: 'Inside the ring (A10)', outside: 'Outside the ring',
  no_preference: 'No preference'
};

const REGISTERED = { yes: 'Yes', no: 'No, arriving from abroad' };

const SOURCES = {
  chatgpt: 'ChatGPT or another AI', instagram: 'Instagram', facebook: 'Facebook',
  tiktok: 'TikTok', google_ads: 'Google Ads', whatsapp: 'WhatsApp Housing Group',
  advertisement: 'Advertisement', kamernet: 'Kamernet', jay: 'Jay',
  employee: 'One of our employees', referral: 'Friend or relative', other: 'Other'
};

const DURATIONS = {
  '6mo': '6 months', '1yr': '1 year', 'more': 'Long term',
  '1mo': '1 month', '3mo': '3 months', '1y': '1 year', '2y': '2 years',
  '3y+': '3+ years', indefinite: 'Indefinite', '<3mo': 'Less than 3 months'
};

// --- Helpers -----------------------------------------------------------------
function humanize(val) {
  if (!val) return null;
  return String(val).split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

// Look a value up in a label map, falling back to a tidied version of the raw
// value so an option we add to the form later still lands somewhere readable.
function label(map, val) {
  if (!val) return null;
  return map[String(val)] || humanize(val);
}

function formatDate(d, m, y) {
  if (!d || !m || !y) return null;
  return d + ' ' + m + ' ' + y;
}

function mondayDate(d, m, y) {
  if (!d || !m || !y) return "";

  // Clean the year: "1993 рік" -> "1993"
  const yearMatch = String(y).match(/\d{4}/);
  if (!yearMatch) return "";
  const yyyy = yearMatch[0];

  // The form submits English month values, but a browser-translated page (or an
  // older submission) can send a localised name, so keep the aliases.
  const months = {
    // English
    january:'01', february:'02', march:'03', april:'04', may:'05', june:'06',
    july:'07', august:'08', september:'09', october:'10', november:'11', december:'12',
    // Dutch
    januari:'01', februari:'02', maart:'03', mei:'05', juni:'06', juli:'07',
    augustus:'08', oktober:'10',
    // Spanish
    enero:'01', febrero:'02', marzo:'03', abril:'04', mayo:'05', junio:'06',
    julio:'07', agosto:'08', septiembre:'09', octubre:'10', noviembre:'11', diciembre:'12',
    // French
    janvier:'01', 'février':'02', fevrier:'02', mars:'03', avril:'04', mai:'05',
    juin:'06', juillet:'07', 'août':'08', aout:'08', novembre:'11', 'décembre':'12',
    decembre:'12',
    // Turkish
    ocak:'01', 'şubat':'02', mart:'03', nisan:'04', 'mayıs':'05', haziran:'06',
    temmuz:'07', 'ağustos':'08', 'eylül':'09', ekim:'10', 'kasım':'11', 'aralık':'12',
    // Ukrainian
    'січень':'01', 'лютий':'02', 'березень':'03', 'квітень':'04', 'травень':'05',
    'червень':'06', 'липень':'07', 'серпень':'08', 'вересень':'09',
    'жовтень':'10', 'листопад':'11', 'грудень':'12'
  };

  let mm = null;
  if (/^\d{1,2}$/.test(String(m))) {
    mm = String(m).padStart(2, '0');
  } else {
    mm = months[String(m).trim().toLowerCase()] || null;
  }
  if (!mm) return ""; // unknown month -> empty date, never junk

  const dd = String(d).padStart(2, '0');
  return { date: `${yyyy}-${mm}-${dd}` };
}

function euros(v, suffix) {
  if (!v) return 'Not provided';
  const num = parseInt(v, 10);
  if (isNaN(num)) return String(v);
  return '€' + num.toLocaleString('en-US') + (suffix || '');
}

function cleanPhone(p) {
  if (!p) return '';
  return String(p).replace(/\D/g, '');
}

function text(v) {
  const s = (v == null ? '' : String(v)).trim();
  return s || null;
}

let lead;
let dobObj;

// Form submission date (Amsterdam time, YYYY-MM-DD for Monday date columns)
const now = new Date();
const submittedDateObj = {
  date: now.toLocaleDateString('en-CA', { timeZone: 'Europe/Amsterdam' })
};

const submittedAt = now.toLocaleString('en-GB', {
  timeZone: 'Europe/Amsterdam',
  dateStyle: 'long',
  timeStyle: 'short'
});

if (isBuy) {
  dobObj = mondayDate(data.b_dob_day, data.b_dob_month, data.b_dob_year);

  lead = {
    mode: 'BUY',
    modeIcon: '🔴',
    isBuy: true,

    firstName: (data.b_full_name || 'there').split(' ')[0],
    fullName: data.b_full_name || 'Unknown',
    dateOfBirth: formatDate(data.b_dob_day, data.b_dob_month, data.b_dob_year) || 'Not provided',
    language: 'Not provided',
    nlRegistered: 'Not provided',
    situation: 'Not provided',
    profession: 'Not provided',
    household: 'Not provided',

    email: data.b_email || 'Not provided',
    phone: data.b_phone || 'Not provided',

    fullAddress: [data.b_address, data.b_city_current, data.b_zip, data.b_country].filter(Boolean).join(', ') || 'Not provided',

    targetCity: data.b_search_city || 'Not provided',
    neighbourhood: data.b_neighbourhood || 'Not provided',
    ring: 'Not provided',
    homeType: humanize(data.b_property_type) || 'Not provided',
    homeTypeLong: humanize(data.b_property_type) || 'Not provided',
    furnished: 'Not provided',
    budget: euros(data.b_max_budget),
    duration: 'Not provided',
    moveInDate: label(DURATIONS, data.b_timeframe) || 'Not provided',

    // Buy-specific
    minBedrooms: data.b_min_bedrooms || 'Not provided',
    mortgageAdvice: humanize(data.b_mortgage_advice) || 'Not provided',
    income: euros(data.b_income),
    contract: humanize(data.b_contract) || 'Not provided',
    savings: humanize(data.b_savings) || 'Not provided',
    debts: humanize(data.b_bkr) || 'Not provided',
    tenure: humanize(data.b_tenure) || 'Not provided',
    timeframe: label(DURATIONS, data.b_timeframe) || 'Not provided',
    requirements: text(data.b_requirements),
    about: text(data.b_requirements),

    source: 'Not provided',
    referralName: 'Not provided',
    submittedAt
  };
} else {
  dobObj = mondayDate(data.dob_day, data.dob_month, data.dob_year);

  // "Other" city is a free-text answer on the new form.
  const targetCity = (String(data.search_city || '').toLowerCase() === 'other')
    ? (text(data.search_city_other) || 'Other (not specified)')
    : (data.search_city || 'Not provided');

  lead = {
    mode: 'RENT',
    modeIcon: '🟢',
    isBuy: false,

    firstName: data.first_name || 'there',
    fullName: [data.first_name, data.last_name].filter(Boolean).join(' ') || 'Unknown',
    lastName: data.last_name || '',
    dateOfBirth: formatDate(data.dob_day, data.dob_month, data.dob_year) || 'Not provided',
    language: label(LANGUAGES, data.language) || 'Not provided',
    nlRegistered: label(REGISTERED, data.nl_registered) || 'Not provided',
    situation: label(SITUATIONS, data.situation || data.occupation) || 'Not provided',
    profession: text(data.profession) || 'Not provided',
    household: label(HOUSEHOLDS, data.household || data.living) || 'Not provided',

    email: data.email || 'Not provided',
    phone: data.phone || 'Not provided',

    fullAddress: [data.address, data.address2, data.city_current, data.zip, data.country].filter(Boolean).join(', ') || 'Not provided',

    targetCity,
    neighbourhood: text(data.search_area) || 'Not provided',
    ring: label(RINGS, data.ams_ring) || 'Not provided',
    homeType: label(HOME_TYPES, data.home_type) || 'Not provided',
    homeTypeLong: label(HOME_TYPES_LONG, data.home_type) || 'Not provided',
    furnished: label(FURNISHED, data.furnished) || 'Not provided',
    budget: euros(data.budget, ' / month'),
    income: euros(data.gross_income, ' / month gross'),
    duration: label(DURATIONS, data.duration) || 'Not provided',
    moveInDate: formatDate(data.movein_day, data.movein_month, data.movein_year) || 'Not provided',

    // Buy-specific (empty for rent)
    minBedrooms: 'Not provided',
    mortgageAdvice: 'Not provided',
    contract: 'Not provided',
    savings: 'Not provided',
    debts: 'Not provided',
    tenure: 'Not provided',
    timeframe: 'Not provided',
    requirements: null,
    about: text(data.about),

    source: label(SOURCES, data.source) || 'Not provided',
    referralName: text(data.referral_name) || 'Not provided',
    submittedAt
  };
}

const phoneClean = cleanPhone(lead.phone);
lead.whatsappLink = phoneClean ? 'https://wa.me/' + phoneClean : null;
lead.telLink = phoneClean ? 'tel:+' + phoneClean : null;

// --- Monday.com payloads -----------------------------------------------------
// Buying board — unchanged.
lead.mondayColumnValues = JSON.stringify({
  "text_mkvdq9af": lead.fullName || "",
  "date_mkvdm4bw": dobObj,
  "text_mkvdjs22": lead.phone || "",
  "text_mkvd965b": lead.targetCity || "",
  "text_mkvda4cf": lead.budget || "",
  "text_mkvdgwb4": lead.email || "",
  "text_mkvdmsas": lead.fullAddress || "",
  "text_mkvdb5n6": lead.neighbourhood || "",
  "text_mkvdczvk": lead.homeType || "",
  "text_mkvd6w45": lead.minBedrooms || "",
  "text_mkvd4c0q": lead.mortgageAdvice || "",
  "text_mkvdtpaq": lead.requirements || "",
  "text_mkvd15qs": lead.income || "",
  "text_mkvd217h": lead.contract || "",
  "text_mkvdnpgq": lead.savings || "",
  "text_mkvd28z6": lead.debts || "",
  "text_mkvdym30": lead.tenure || "",
  "text_mkvdrjxf": lead.timeframe || "",
  "date4": submittedDateObj
});

// Renting board — driven by RENT_COLUMNS, so a column id you haven't created
// yet is left out of the payload instead of breaking the request.
const rentValues = {};
function setRentColumn(key, value) {
  const columnId = RENT_COLUMNS[key];
  if (!columnId) return;
  rentValues[columnId] = (value === null || value === undefined) ? "" : value;
}

setRentColumn('firstName',    lead.firstName);
setRentColumn('lastName',     lead.lastName || lead.fullName.split(' ').slice(1).join(' '));
setRentColumn('dateOfBirth',  dobObj);
setRentColumn('language',     lead.language);
setRentColumn('situation',    lead.situation);
setRentColumn('profession',   lead.profession);
setRentColumn('grossIncome',  lead.income);
setRentColumn('targetCity',   lead.targetCity);
setRentColumn('neighbourhood',lead.neighbourhood);
setRentColumn('ring',         lead.ring);
setRentColumn('budget',       lead.budget);
setRentColumn('homeType',     lead.homeType);
setRentColumn('duration',     lead.duration);
setRentColumn('household',    lead.household);
setRentColumn('phone',        lead.phone);
setRentColumn('email',        lead.email);
setRentColumn('nlRegistered', lead.nlRegistered);
setRentColumn('fullAddress',  lead.fullAddress);
setRentColumn('moveInDate',   lead.moveInDate);
setRentColumn('furnished',    lead.furnished);
setRentColumn('source',       lead.source);
setRentColumn('referralName', lead.referralName);
setRentColumn('about',        lead.about);
setRentColumn('submittedAt',  submittedDateObj);

lead.mondayColumnValuesRent = JSON.stringify(rentValues);

return [{ json: lead }];

