==<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, 'Inter', sans-serif; background: #F2EBDD; margin: 0; padding: 32px 16px; color: #13241F; }
  .container { max-width: 580px; margin: 0 auto; background: #FAF6ED; border-radius: 12px; padding: 36px; border: 1px solid rgba(19,36,31,0.08); }
  .eyebrow { font-size: 11px; letter-spacing: 1.8px; text-transform: uppercase; color: #B85C38; margin-bottom: 8px; font-weight: 500; }
  h1 { font-family: 'Georgia', serif; font-weight: 300; font-size: 28px; letter-spacing: -0.5px; margin: 0 0 16px 0; color: #13241F; }
  .badge { display: inline-block; padding: 5px 14px; border-radius: 999px; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; font-weight: 600; margin-bottom: 24px; }
  .badge-rent { background: rgba(169,132,84,0.15); color: #A98454; }
  .badge-buy { background: rgba(184,92,56,0.15); color: #B85C38; }
  .section-header { font-size: 11px; text-transform: uppercase; letter-spacing: 1.5px; color: #B85C38; margin: 28px 0 4px 0; font-weight: 600; }
  .row { display: flex; padding: 11px 0; border-bottom: 1px solid rgba(19,36,31,0.08); }
  .row:last-child { border-bottom: none; }
  .label { width: 150px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.6px; color: #6E6759; font-weight: 500; padding-top: 2px; }
  .value { flex: 1; font-size: 14px; color: #13241F; line-height: 1.5; }
  .value strong { color: #13241F; }
  .about-box { margin-top: 8px; padding: 18px 20px; background: rgba(184,92,56,0.06); border-left: 3px solid #B85C38; border-radius: 4px; font-style: italic; font-size: 14px; color: #13241F; line-height: 1.6; }
  .meta { margin-top: 32px; padding-top: 20px; border-top: 1px solid rgba(19,36,31,0.08); font-size: 11px; color: #6E6759; line-height: 1.6; text-align: center; }
  a { color: #B85C38; text-decoration: none; }
</style>
</head>
<body>
  <div class="container">
    <div class="eyebrow">— New lead via hqhousing.com —</div>
    <h1>{{ $('Normalize Lead Data').item.json.fullName }}</h1>

    <div class="badge {{ $('Normalize Lead Data').item.json.isBuy ? 'badge-buy' : 'badge-rent' }}">
      {{ $('Normalize Lead Data').item.json.modeIcon }} &nbsp; Looking to {{ $('Normalize Lead Data').item.json.isBuy ? 'buy' : 'rent' }} in {{ $('Normalize Lead Data').item.json.targetCity }}
    </div>

    <table cellpadding="0" cellspacing="0" border="0" style="margin: 0 0 28px 0; width: 100%;">
      <tr>
        <td style="padding-right: 8px;">
          <a href="mailto:{{ $('Normalize Lead Data').item.json.email }}" style="display: block; padding: 14px 20px; background: #B85C38; color: #FAF6ED; text-decoration: none; border-radius: 999px; font-size: 12px; letter-spacing: 0.8px; text-transform: uppercase; font-weight: 500; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Inter', sans-serif;">Reply by email →</a>
        </td>
        <td style="padding-left: 8px;">
          {{ $('Normalize Lead Data').item.json.whatsappLink ? '<a href="' + $('Normalize Lead Data').item.json.whatsappLink + '" style="display: block; padding: 14px 20px; background: #25D366; color: #FFFFFF; text-decoration: none; border-radius: 999px; font-size: 12px; letter-spacing: 0.8px; text-transform: uppercase; font-weight: 500; text-align: center; font-family: -apple-system, BlinkMacSystemFont, sans-serif;">WhatsApp</a>' : '' }}
        </td>
      </tr>
    </table>

    {{ $('Normalize Lead Data').item.json.telLink ? '<a href="' + $('Normalize Lead Data').item.json.telLink + '" style="display: block; margin-bottom: 28px; padding: 20px; background: rgba(184,92,56,0.06); border: 1px solid rgba(184,92,56,0.25); border-radius: 12px; text-align: center; text-decoration: none; color: #13241F;"><div style="font-size: 10px; letter-spacing: 1.4px; text-transform: uppercase; color: #6E6759; margin-bottom: 6px; font-family: -apple-system, BlinkMacSystemFont, sans-serif;">📞 Tap to call (or copy the number)</div><div style="font-family: Georgia, serif; font-size: 24px; color: #13241F; font-weight: 400; letter-spacing: 0.5px;">' + $('Normalize Lead Data').item.json.phone + '</div></a>' : '' }}

    <div class="section-header">Contact</div>
    <div class="row"><div class="label">Email</div><div class="value"><a href="mailto:{{ $('Normalize Lead Data').item.json.email }}">{{ $('Normalize Lead Data').item.json.email }}</a></div></div>
    <div class="row"><div class="label">Phone</div><div class="value">{{ $('Normalize Lead Data').item.json.phone }}</div></div>
    <div class="row"><div class="label">Speaks</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.language }}</strong></div></div>

    <div class="section-header">Personal</div>
    <div class="row"><div class="label">Date of birth</div><div class="value">{{ $('Normalize Lead Data').item.json.dateOfBirth }}</div></div>
    <div class="row"><div class="label">Registered in NL</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.nlRegistered }}</strong></div></div>
    <div class="row"><div class="label">Household</div><div class="value">{{ $('Normalize Lead Data').item.json.household }}</div></div>

    <div class="section-header">Work &amp; income</div>
    <div class="row"><div class="label">Situation</div><div class="value">{{ $('Normalize Lead Data').item.json.situation }}</div></div>
    <div class="row"><div class="label">Profession / studies</div><div class="value">{{ $('Normalize Lead Data').item.json.profession }}</div></div>
    <div class="row"><div class="label">Gross salary</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.income }}</strong></div></div>
    <div class="row"><div class="label">Max budget</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.budget }}</strong></div></div>

    <div class="section-header">Currently lives at</div>
    <div class="row"><div class="label">Address</div><div class="value">{{ $('Normalize Lead Data').item.json.fullAddress }}</div></div>

    <div class="section-header">Looking for</div>
    <div class="row"><div class="label">Target city</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.targetCity }}</strong></div></div>
    {{ $('Normalize Lead Data').item.json.ring !== 'Not provided' ? '<div class="row"><div class="label">A10 ring</div><div class="value">' + $('Normalize Lead Data').item.json.ring + '</div></div>' : '' }}
    {{ $('Normalize Lead Data').item.json.neighbourhood !== 'Not provided' ? '<div class="row"><div class="label">Area</div><div class="value">' + $('Normalize Lead Data').item.json.neighbourhood + '</div></div>' : '' }}
    <div class="row"><div class="label">Home type</div><div class="value">{{ $('Normalize Lead Data').item.json.homeTypeLong }}</div></div>
    <div class="row"><div class="label">Furnished</div><div class="value">{{ $('Normalize Lead Data').item.json.furnished }}</div></div>
    <div class="row"><div class="label">Duration</div><div class="value">{{ $('Normalize Lead Data').item.json.duration }}</div></div>
    <div class="row"><div class="label">Desired move-in</div><div class="value"><strong>{{ $('Normalize Lead Data').item.json.moveInDate }}</strong></div></div>

    {{ $('Normalize Lead Data').item.json.about ? '<div class="section-header">In their own words</div><div class="about-box">' + $('Normalize Lead Data').item.json.about + '</div>' : '' }}

    <div class="section-header">Source</div>
    <div class="row"><div class="label">How they found us</div><div class="value">{{ $('Normalize Lead Data').item.json.source }}</div></div>
    {{ $('Normalize Lead Data').item.json.referralName !== 'Not provided' ? '<div class="row"><div class="label">Referred by</div><div class="value"><strong>' + $('Normalize Lead Data').item.json.referralName + '</strong></div></div>' : '' }}

    <div class="meta">
      Submitted {{ $('Normalize Lead Data').item.json.submittedAt }} CET
    </div>
  </div>
</body>
</html>
